SELECT COUNT(*)
FROM bond
WHERE bond_type = '#';

SELECT atom_id
FROM atom
WHERE atom_id LIKE 'TR186_%';

SELECT DISTINCT setCode
FROM sets
WHERE type = 'expansion' AND commander = 'commander';

SELECT 
    ROUND(
        (
            SUM(gender = 'Female' WHERE publisher_name = 'Marvel Comics')
        ) / COUNT(publisher_name = 'Marvel Comics') * 100
    ) as percent
FROM gender g
JOIN publisher p ON g.publisher_id = p.id
WHERE p.publisher_name = 'Marvel Comics'
  AND g.gender = 'Female';

SELECT DISTINCT e.expense_id, e.expense_description
FROM expense e
WHERE e.cost > 50.0;
